import React, { useCallback, useEffect, useMemo, useState } from "react";
import { api, cachedGet, download, flushQueue, getToken, mutate, queuedCount, setToken, upload } from "./api";

const NAV = [
  ["dashboard", "Pulpit", "▦"], ["projects", "Projekty", "◆"], ["structure", "Strefy i rzędy", "▤"],
  ["reports", "Meldunki", "◷"], ["logistics", "Zapotrzebowanie", "⌗"],
  ["documents", "Dokumenty", "▱"], ["rfi", "RFI / problemy", "!"], ["users", "Użytkownicy", "♙"],
];
const TRACKER_VARIANTS = ["1x28", "1x42", "1x56", "1x70", "1x42+1x28", "1x56+1x28", "1x56+1x42"];
const today = () => new Date().toISOString().slice(0, 10);
const uid = () => crypto.randomUUID?.() || `${Date.now()}-${Math.random()}`;
const fmt = value => value ? new Intl.DateTimeFormat("pl-PL", { dateStyle: "medium", timeStyle: String(value).includes("T") ? "short" : undefined }).format(new Date(value)) : "—";
const pct = (value, total) => total ? Math.round(value / total * 100) : 0;
const emptyMaterials = () => ({ "1": 0, "2": 0, "3": 0 });
const roleName = role => ({ kierownik: "Kierownik budowy", brygadzista: "Brygadzista", magazynier: "Magazynier" }[role] || role);

function Login({ onLogin }) {
  const [username, setUsername] = useState("kierownik");
  const [password, setPassword] = useState("Asolar2026!");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  async function submit(event) {
    event.preventDefault(); setBusy(true); setError("");
    try {
      const result = await api("/api/auth/login", { method: "POST", body: JSON.stringify({ username, password }), headers: { "Content-Type": "application/json" } });
      setToken(result.token); onLogin(result.user);
    } catch (err) { setError(err.message); } finally { setBusy(false); }
  }
  const accounts = [["kierownik", "Asolar2026!", "Kierownik"], ["brygadzista", "Brygada2026!", "Brygadzista"], ["magazynier", "Magazyn2026!", "Magazynier"]];
  return <main className="login-page">
    <section className="login-brand"><div className="brand-mark large">A</div><p className="eyebrow">ASOLAR ESET</p><h1>Trackery pod kontrolą.</h1><p>Konfiguracja wariantów ESET, automatyczne zapotrzebowanie BOM, meldunki i jakość na farmie PV.</p><div className="login-feature"><span>✓</span> 4 warianty podstawowe i 3 warianty łączone</div><div className="login-feature"><span>✓</span> Zapotrzebowanie według manuali ESET</div><div className="login-feature"><span>✓</span> Praca mobilna i kolejka offline</div></section>
    <section className="login-panel"><form className="login-card" onSubmit={submit}><div className="mobile-brand"><div className="brand-mark">A</div><strong>ASOLAR</strong></div><p className="eyebrow">ESET TRACKER MANAGER</p><h2>Zaloguj się</h2><label>Login<input value={username} onChange={e => setUsername(e.target.value)} autoComplete="username" /></label><label>Hasło<input type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" /></label>{error && <div className="alert error">{error}</div>}<button className="primary wide" disabled={busy}>{busy ? "Logowanie…" : "Zaloguj się"}</button><div className="demo-accounts"><span>Konta startowe</span>{accounts.map(([u, p, name]) => <button type="button" key={u} onClick={() => { setUsername(u); setPassword(p); }}>{name}</button>)}</div></form></section>
  </main>;
}

function PageHead({ eyebrow, title, children }) { return <div className="page-head"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1></div><div className="head-actions">{children}</div></div>; }
function Empty({ children }) { return <div className="empty"><span>◇</span><p>{children}</p></div>; }
function Loader() { return <div className="loading"><i /><span>Ładowanie danych…</span></div>; }
function Progress({ value }) { return <div className="progress"><i style={{ width: `${Math.min(100, Math.max(0, value))}%` }} /></div>; }

function PhotoGallery({ entityType, entityId, refresh = 0, notify }) {
  const [photos, setPhotos] = useState([]);
  useEffect(() => {
    let active = true; const urls = [];
    (async () => {
      try {
        const list = await api(`/api/${entityType}/${entityId}/photos`);
        const loaded = await Promise.all(list.map(async item => { const blob = await api(item.url); const url = URL.createObjectURL(blob); urls.push(url); return { ...item, url }; }));
        if (active) setPhotos(loaded);
      } catch (error) { if (active) notify?.(error.message, "error"); }
    })();
    return () => { active = false; urls.forEach(URL.revokeObjectURL); };
  }, [entityType, entityId, refresh]);
  if (!photos.length) return null;
  return <div className="photo-gallery">{photos.map(photo => <a href={photo.url} target="_blank" rel="noreferrer" key={photo.id}><img src={photo.url} alt={photo.filename} /><small>{fmt(photo.created_at)}</small></a>)}</div>;
}

function Dashboard({ project, sync, notify, user }) {
  const [data, setData] = useState(null); const [demand, setDemand] = useState(null); const [rfis, setRfis] = useState([]);
  const load = useCallback(async () => { if (!project) return; try { const [a, b, c] = await Promise.all([cachedGet(`/api/dashboard?project_id=${project.id}`), cachedGet(`/api/projects/${project.id}/tracker-config`), cachedGet(`/api/rfis?project_id=${project.id}`)]); setData(a); setDemand(b); setRfis(c); } catch (e) { notify(e.message, "error"); } }, [project, sync]);
  useEffect(() => { load(); }, [load]);
  if (!project) return <Empty>Dodaj aktywny projekt, aby rozpocząć.</Empty>;
  if (!data) return <Loader />;
  return <><PageHead eyebrow="CENTRUM OPERACYJNE" title={`Dzień dobry, ${user.full_name.split(" ")[0]}`}><span className="badge neutral">{project.structure_type || "typ dowolny"}</span></PageHead>
    <section className="kpi-grid"><article className="kpi hero-kpi"><span>Postęp konstrukcji</span><strong>{data.completion_pct}%</strong><Progress value={data.completion_pct} /><small>{data.rows_built} z {data.rows_total} rzędów</small></article><article className="kpi"><div className="kpi-icon green">✓</div><span>Odbiór QA/QC</span><strong>{data.rows_qc}<small> / {data.rows_total}</small></strong><Progress value={data.qc_pct} /></article><article className="kpi"><div className="kpi-icon amber">!</div><span>Otwarte RFI</span><strong>{data.open_rfi}</strong></article><article className="kpi"><div className="kpi-icon blue">◷</div><span>Wydajność</span><strong>{data.productivity}<small> rz./rbh</small></strong><small>{data.manhours} rbh</small></article><article className="kpi"><div className="kpi-icon violet">→</div><span>Prognoza</span><strong>{data.forecast_days ?? "—"}<small>{data.forecast_days != null ? " dni" : ""}</small></strong></article></section>
    <div className="split"><section className="card"><div className="card-head"><div><p className="eyebrow">KONFIGURACJA ESET</p><h2>Rzędy objęte zapotrzebowaniem</h2></div><strong>{demand?.total_modules || 0} modułów</strong></div><div className="variant-compact">{demand?.variants.map(item => <div key={item.code}><span>{item.code}</span><strong>{item.row_count}</strong><small>rzędów</small></div>)}</div>{!demand?.total_rows && <p className="hint">Ustaw liczbę rzędów w module Konfiguracja.</p>}</section><section className="card"><div className="card-head"><h2>Ostatnie RFI</h2></div>{rfis.slice(0, 4).map(item => <div className="rfi-mini" key={item.id}><span className={`priority ${item.priority}`} /><div><strong>#{item.id} {item.title}</strong><small>{item.status} · {fmt(item.created_at)}</small></div></div>)}{!rfis.length && <Empty>Brak otwartych zgłoszeń.</Empty>}</section></div>
  </>;
}

function Projects({ projects, reloadProjects, notify, user, setProjectId, projectId }) {
  const blank = { name: "", location: "", capacity_mw: "", structure_type: "tracker / 1-noga" };
  const [form, setForm] = useState(blank); const [editing, setEditing] = useState(null);
  async function save(event) { event.preventDefault(); try { const body = { ...form, capacity_mw: Number(form.capacity_mw || 0) }; if (editing) await api(`/api/projects/${editing}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); else { const item = await api("/api/projects", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); setProjectId(item.id); } notify(editing ? "Projekt zaktualizowany" : "Projekt utworzony"); setForm(blank); setEditing(null); reloadProjects(); } catch (e) { notify(e.message, "error"); } }
  function edit(item) { setEditing(item.id); setForm({ name: item.name, location: item.location, capacity_mw: item.capacity_mw, structure_type: item.structure_type || "" }); }
  async function archive(item) { try { await api(`/api/projects/${item.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ archived: !item.archived }) }); notify(item.archived ? "Projekt przywrócony" : "Projekt zarchiwizowany"); reloadProjects(); } catch (e) { notify(e.message, "error"); } }
  async function remove(item) { if (!window.confirm(`Usunąć projekt „${item.name}” wraz z jego danymi?`)) return; try { await api(`/api/projects/${item.id}`, { method: "DELETE" }); notify("Projekt usunięty"); if (projectId === item.id) setProjectId(null); reloadProjects(); } catch (e) { notify(e.message, "error"); } }
  return <><PageHead eyebrow="PORTFEL BUDÓW" title="Projekty farm PV"><span className="badge neutral">{projects.filter(x => !x.archived).length} aktywnych</span></PageHead><div className="project-grid">{projects.map(item => <article className={`card project-card ${item.archived ? "archived" : ""}`} key={item.id}><div className="card-head"><span className={`badge ${item.archived ? "neutral" : "success"}`}>{item.archived ? "archiwum" : "aktywny"}</span><strong>{item.capacity_mw} MW</strong></div><h2>{item.name}</h2><p>{item.location || "Brak lokalizacji"}</p><div className="project-type">{item.structure_type || "Typ konstrukcji nieokreślony"}</div>{user.role === "kierownik" && <div className="card-actions"><button onClick={() => edit(item)}>Edytuj</button><button onClick={() => archive(item)}>{item.archived ? "Przywróć" : "Archiwizuj"}</button><button className="danger-button" onClick={() => remove(item)}>Usuń</button></div>}</article>)}</div>{user.role === "kierownik" && <form className="card project-form" onSubmit={save}><div className="card-head"><h2>{editing ? "Edytuj projekt" : "Nowy projekt"}</h2>{editing && <button type="button" className="text-button" onClick={() => { setEditing(null); setForm(blank); }}>Anuluj</button>}</div><div className="form-grid four"><label>Nazwa projektu<input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label><label>Lokalizacja<input value={form.location} onChange={e => setForm({ ...form, location: e.target.value })} /></label><label>Moc [MW]<input type="number" min="0" step="0.01" value={form.capacity_mw} onChange={e => setForm({ ...form, capacity_mw: e.target.value })} /></label><label>Typ struktury<input placeholder="np. tracker, 1-noga, 2-nogi" value={form.structure_type} onChange={e => setForm({ ...form, structure_type: e.target.value })} /></label></div><button className="primary">{editing ? "Zapisz zmiany" : "Dodaj projekt"}</button></form>}</>;
}

function torqueLabel(item) {
  return item.torque_min_nm != null ? `${item.torque_min_nm}–${item.torque_max_nm} N·m` : "—";
}

function VariantBomTable({ items, rowCount }) {
  return <div className="bom-table-wrap"><table className="bom-table"><thead><tr><th>Element</th><th>Specyfikacja</th><th>Na 1 rząd</th><th>Dla {rowCount} rz.</th><th>Moment</th></tr></thead><tbody>{items.map(item => <tr key={item.key}><td><strong>{item.name}</strong><small>{item.category} · {item.key}</small></td><td>{item.spec}<small>{item.source}</small></td><td><b>{item.quantity_per_row}</b> {item.unit}</td><td><b>{item.quantity_per_row * rowCount}</b> {item.unit}</td><td>{torqueLabel(item)}</td></tr>)}</tbody></table></div>;
}

function DemandTable({ items }) {
  return <div className="bom-table-wrap"><table className="bom-table demand-table"><thead><tr><th>Element</th><th>Specyfikacja</th><th>Zapotrzebowanie</th><th>Moment</th></tr></thead><tbody>{items.map(item => <tr key={item.key}><td><strong>{item.name}</strong><small>{item.key}</small></td><td>{item.spec}<small>{item.source}</small></td><td><b>{item.quantity_total}</b> {item.unit}</td><td>{torqueLabel(item)}</td></tr>)}</tbody></table></div>;
}

function TrackerConfigurationLegacy({ project, sync, notify, user }) {
  const [data, setData] = useState(null); const [counts, setCounts] = useState({}); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => { if (!project) return; try { const result = await cachedGet(`/api/projects/${project.id}/tracker-config`); setData(result); setCounts(Object.fromEntries(result.variants.map(item => [item.code, item.row_count]))); } catch (e) { notify(e.message, "error"); } }, [project, sync]);
  useEffect(() => { load(); }, [load]);
  async function save(e) { e.preventDefault(); setBusy(true); try { const items = TRACKER_VARIANTS.map(variant_code => ({ variant_code, row_count: Number(counts[variant_code] || 0) })); const result = await mutate(`/api/projects/${project.id}/tracker-config`, "PUT", { items }); if (result.queued) notify("Konfiguracja zapisana offline — oczekuje na synchronizację"); else { setData(result); setCounts(Object.fromEntries(result.variants.map(item => [item.code, item.row_count]))); notify("Konfiguracja i zapotrzebowanie przeliczone"); } } catch (error) { notify(error.message, "error"); } finally { setBusy(false); } }
  if (!project) return <Empty>Wybierz aktywny projekt.</Empty>; if (!data) return <Loader />;
  const editable = user.role === "kierownik" || user.role === "brygadzista";
  return <><PageHead eyebrow="CZTERY WARIANTY ESET" title="Konfiguracja rzędów"><span className="badge success">{data.total_rows} rzędów · {data.total_modules} modułów</span></PageHead><section className="card config-intro"><div><h2>Wpisz liczbę rzędów każdego wariantu</h2><p>Zapis automatycznie przelicza pełne zapotrzebowanie projektowe. Ilości jednostkowe pozostają zgodne z zatwierdzonymi tabelami BOM.</p></div><span>Tylko 1x28 · 1x42 · 1x56 · 1x70</span></section><form onSubmit={save}><div className="variant-config-grid">{data.variants.map(item => <article className={`card variant-config-card ${item.row_count ? "configured" : ""}`} key={item.code}><div className="variant-title"><div><span>TRACKER ESET</span><h2>{item.code}</h2><small>{item.modules} modułów / rząd</small></div><label>Liczba rzędów<input aria-label={`Liczba rzędów ${item.code}`} type="number" min="0" max="5000" value={counts[item.code] ?? 0} disabled={!editable} onChange={e => setCounts({ ...counts, [item.code]: e.target.value })} /></label></div><div className="variant-stat"><span>W projekcie</span><strong>{item.row_count} rz. · {item.total_modules} modułów</strong></div><details className="variant-bom"><summary>Lista sprzętu i śrub <b>{item.per_row.length} pozycji</b></summary><VariantBomTable items={item.per_row} rowCount={item.row_count} /><p className="source-line">Źródło wariantu: {item.source}</p></details></article>)}</div>{editable && <div className="save-bar"><div><strong>Zapisz wszystkie cztery wartości</strong><small>Po zapisaniu suma projektu i wszystkie pozycje BOM zostaną przeliczone.</small></div><button className="primary" disabled={busy}>{busy ? "Przeliczanie…" : "Zapisz i przelicz"}</button></div>}</form></>;
}

function ModuleReference({ demand, compact = false }) {
  const item = demand?.module;
  if (!item) return null;
  return <div className={`module-reference ${compact ? "compact" : ""}`}><div><span>MODUŁ REFERENCYJNY</span><strong>{item.manufacturer} {item.model}</strong><small>{item.power_min_w}–{item.power_max_w} W · {item.cells} ogniw · {item.dimensions_mm} mm · {item.weight_kg} kg</small></div><div><span>MOC DLA TEJ KONFIGURACJI</span><strong>{demand.estimated_power_min_mw}–{demand.estimated_power_max_mw} MWp</strong><small>{demand.total_modules} modułów · {item.packing}</small></div></div>;
}

function ZoneConfigurationCard({ zone, editable, canDelete, onChanged, onDeleted, notify }) {
  const initialCounts = () => Object.fromEntries(zone.demand.variants.map(item => [item.code, item.row_count]));
  const [counts, setCounts] = useState(initialCounts); const [name, setName] = useState(zone.name); const [busy, setBusy] = useState(false);
  useEffect(() => { setCounts(initialCounts()); setName(zone.name); }, [zone]);
  async function save() { setBusy(true); try { const items = TRACKER_VARIANTS.map(variant_code => ({ variant_code, row_count: Number(counts[variant_code] || 0) })); const result = await mutate(`/api/tracker-zones/${zone.id}/config`, "PUT", { items }); notify(result.queued ? "Konfiguracja strefy zapisana offline" : "Strefa przeliczona, a lista rzędów zaktualizowana"); if (!result.queued) onChanged(); } catch (error) { notify(error.message, "error"); } finally { setBusy(false); } }
  async function rename() { const clean = name.trim(); if (!clean || clean === zone.name) return; try { const result = await mutate(`/api/tracker-zones/${zone.id}`, "PATCH", { name: clean }); notify(result.queued ? "Nazwa zapisana offline" : "Nazwa strefy zmieniona"); if (!result.queued) onChanged(); } catch (error) { notify(error.message, "error"); } }
  async function remove() { if (!window.confirm(`Usunąć strefę „${zone.name}” wraz z wygenerowanymi rzędami i zdjęciami?`)) return; try { await api(`/api/tracker-zones/${zone.id}`, { method: "DELETE" }); notify("Strefa usunięta"); onDeleted(); } catch (error) { notify(error.message, "error"); } }
  return <article className="card zone-config-card"><div className="zone-card-head"><div className="zone-name"><span>STREFA</span>{editable ? <div><input aria-label="Nazwa strefy" value={name} onChange={e => setName(e.target.value)} /><button type="button" onClick={rename}>Zapisz nazwę</button></div> : <h2>{zone.name}</h2>}</div><div className="zone-progress"><strong>{zone.stats.built}/{zone.stats.total}</strong><span>zbudowane</span><Progress value={pct(zone.stats.built, zone.stats.total)} /></div>{canDelete && <button className="zone-delete" type="button" onClick={remove} title="Usuń strefę">×</button>}</div><div className="zone-variant-grid">{zone.demand.variants.map(item => <label className={item.composition ? "combined" : ""} key={item.code}><span>{item.code}<small>{item.composition ? "wariant łączony · " : ""}{item.modules} modułów</small></span><input type="number" min="0" max="5000" inputMode="numeric" value={counts[item.code] ?? 0} disabled={!editable} onChange={e => setCounts({ ...counts, [item.code]: e.target.value })} /></label>)}</div><div className="zone-totals"><span><b>{zone.demand.total_rows}</b> rzędów</span><span><b>{zone.demand.total_modules}</b> modułów</span><span><b>{zone.stats.qc}</b> odebranych QA/QC</span>{editable && <button className="primary" type="button" disabled={busy} onClick={save}>{busy ? "Przeliczanie…" : "Zapisz i generuj rzędy"}</button>}</div><ModuleReference demand={zone.demand} compact /><details className="variant-bom zone-bom"><summary>Zapotrzebowanie materiałowe strefy <b>{zone.demand.grand_total.length} pozycji</b></summary>{zone.demand.total_rows ? <DemandTable items={zone.demand.grand_total} /> : <p className="hint">Wpisz liczbę rzędów, aby wyliczyć BOM strefy.</p>}</details></article>;
}

function ZoneConfigurationView({ project, sync, notify, user, onOpenRows }) {
  const [zones, setZones] = useState([]); const [name, setName] = useState(""); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => { if (!project) return; try { setZones(await cachedGet(`/api/projects/${project.id}/tracker-zones`)); } catch (error) { notify(error.message, "error"); } }, [project, sync]);
  useEffect(() => { load(); }, [load]);
  const editable = user.role === "kierownik" || user.role === "brygadzista";
  async function create(event) { event.preventDefault(); if (!name.trim()) return; setBusy(true); try { const result = await mutate("/api/tracker-zones", "POST", { project_id: project.id, name: name.trim() }); notify(result.queued ? "Strefa zapisana offline" : "Strefa utworzona"); setName(""); if (!result.queued) load(); } catch (error) { notify(error.message, "error"); } finally { setBusy(false); } }
  return <><section className="card zone-guide"><div><strong>1. Utwórz strefę</strong><small>Nadaj jej własną nazwę.</small></div><i>→</i><div><strong>2. Wpisz warianty</strong><small>Ustaw liczby 4 wariantów podstawowych i 3 łączonych.</small></div><i>→</i><div><strong>3. Pracuj na rzędach</strong><small>System utworzy każdą pozycję i policzy BOM.</small></div></section>{editable && <form className="card zone-create" onSubmit={create}><label>Nazwa nowej strefy<input required placeholder="np. Strefa A — północ" value={name} onChange={e => setName(e.target.value)} /></label><button className="primary" disabled={busy}>{busy ? "Tworzenie…" : "+ Dodaj strefę"}</button></form>}<div className="zone-config-list">{zones.map(zone => <ZoneConfigurationCard key={zone.id} zone={zone} editable={editable} canDelete={user.role === "kierownik"} onChanged={load} onDeleted={load} notify={notify} />)}</div>{!zones.length && <Empty>Nie ma jeszcze stref. Dodaj pierwszą strefę i wpisz liczbę rzędów.</Empty>}{!!zones.length && <button className="open-operations primary" onClick={onOpenRows}>Przejdź do widoku operacyjnego →</button>}</>;
}

function OperationalRowCard({ row, user, onUpdate, onMove, canMoveUp, canMoveDown, canReorder, notify }) {
  const [open, setOpen] = useState(false); const [note, setNote] = useState(row.note || ""); const [photoRefresh, setPhotoRefresh] = useState(0); const [busy, setBusy] = useState(false);
  useEffect(() => setNote(row.note || ""), [row.note]);
  async function saveNote() { setBusy(true); await onUpdate(row.id, { note }, "Notatka rzędu zapisana"); setBusy(false); }
  async function photo(file) { if (!file) return; const fd = new FormData(); fd.append("file", file); try { await upload(`/api/row/${row.id}/photos`, fd); notify("Zdjęcie przypisane do rzędu"); setPhotoRefresh(value => value + 1); } catch (error) { notify(error.message, "error"); } }
  const canWork = user.role === "kierownik" || user.role === "brygadzista";
  return <article className={`operational-row card ${row.qc_checked ? "verified" : row.built ? "built" : ""}`}><div className="operational-row-main"><button className="operational-identity" onClick={() => setOpen(value => !value)}><span>RZĄD {row.code}</span><strong>{row.variant_name}</strong><small>{row.zone_name}</small></button><div className="order-controls" title={canReorder ? "Ustaw kolejność na placu" : "Sortowanie jest dostępne w widoku wszystkich statusów"}><button disabled={!canReorder || !canMoveUp} onClick={() => onMove(row.id, "up")} aria-label={`Przesuń rząd ${row.code} w górę`}>↑<small>Góra</small></button><button disabled={!canReorder || !canMoveDown} onClick={() => onMove(row.id, "down")} aria-label={`Przesuń rząd ${row.code} w dół`}>↓<small>Dół</small></button></div><button className={`operational-status ${row.built ? "done" : ""}`} disabled={!canWork} onClick={() => onUpdate(row.id, { built: !row.built }, row.built ? "Cofnięto status montażu" : "Rząd oznaczony jako zbudowany")}><i>{row.built ? "✓" : "○"}</i><span>{row.built ? "Zbudowany" : "Do zrobienia"}<small>{row.built_by || "Montaż"}</small></span></button><button className={`operational-status ${row.qc_checked ? "qc" : ""}`} disabled={user.role !== "kierownik" || !row.built} onClick={() => onUpdate(row.id, { qc_checked: !row.qc_checked }, row.qc_checked ? "Cofnięto odbiór QA/QC" : "Rząd odebrany QA/QC")}><i>{row.qc_checked ? "✓" : "○"}</i><span>{row.qc_checked ? "Sprawdzony" : "QA/QC"}<small>{row.qc_by || (row.built ? "Odbiera kierownik" : "Najpierw montaż")}</small></span></button><button className="row-detail-button" onClick={() => setOpen(value => !value)}>{open ? "Zamknij" : `Uwagi i zdjęcia${row.photos ? ` (${row.photos})` : ""}`}</button></div>{open && <div className="operational-detail"><label>Indywidualne notatki terenowe<textarea rows="3" placeholder="Uwagi, kolizje, poprawki…" value={note} disabled={!canWork} onChange={e => setNote(e.target.value)} /></label><div className="operational-detail-actions">{canWork && <button className="secondary" disabled={busy} onClick={saveNote}>{busy ? "Zapisywanie…" : "Zapisz notatkę"}</button>}{canWork && <label className="camera-button compact-camera"><input type="file" accept="image/*" capture="environment" onChange={e => photo(e.target.files[0])} /><span>▧</span>Zrób lub dodaj zdjęcie</label>}</div><PhotoGallery entityType="row" entityId={row.id} refresh={photoRefresh} notify={notify} /></div>}</article>;
}

function OperationalRowsView({ project, sync, notify, user }) {
  const [zones, setZones] = useState([]); const [rows, setRows] = useState([]); const [zoneId, setZoneId] = useState(""); const [filter, setFilter] = useState("all");
  const load = useCallback(async () => { if (!project) return; try { const [zoneData, rowData] = await Promise.all([cachedGet(`/api/projects/${project.id}/tracker-zones`), cachedGet(`/api/projects/${project.id}/operational-rows`)]); setZones(zoneData); setRows(rowData); } catch (error) { notify(error.message, "error"); } }, [project, sync]);
  useEffect(() => { load(); }, [load]);
  async function update(id, payload, message) { try { const result = await mutate(`/api/rows/${id}`, "PATCH", payload); notify(result.queued ? `${message} — zapis offline` : message); setRows(current => current.map(row => row.id === id ? { ...row, ...payload, ...(payload.built === false ? { qc_checked: false } : {}) } : row)); if (!result.queued) load(); } catch (error) { notify(error.message, "error"); } }
  async function move(id, direction) { try { const result = await mutate(`/api/rows/${id}/move`, "POST", { direction }); setRows(current => { const selected = current.find(row => row.id === id); if (!selected) return current; const inZone = current.filter(row => row.zone_id === selected.zone_id).sort((a, b) => a.sort_order - b.sort_order); const index = inZone.findIndex(row => row.id === id); const target = direction === "up" ? index - 1 : index + 1; if (target < 0 || target >= inZone.length) return current; [inZone[index], inZone[target]] = [inZone[target], inZone[index]]; const positions = new Map(inZone.map((row, position) => [row.id, position + 1])); return current.map(row => positions.has(row.id) ? { ...row, sort_order: positions.get(row.id), code: String(positions.get(row.id)) } : row).sort((a, b) => a.zone_id - b.zone_id || a.sort_order - b.sort_order); }); notify(result.queued ? "Nowa kolejność zapisana offline" : "Kolejność rzędów zapisana"); if (!result.queued) load(); } catch (error) { notify(error.message, "error"); } }
  const visible = rows.filter(row => (!zoneId || row.zone_id === Number(zoneId)) && (filter === "all" || (filter === "todo" && !row.built) || (filter === "built" && row.built && !row.qc_checked) || (filter === "qc" && row.qc_checked)));
  const built = rows.filter(row => row.built).length; const qc = rows.filter(row => row.qc_checked).length;
  const position = new Map(); for (const zone of zones) { const inZone = rows.filter(row => row.zone_id === zone.id).sort((a, b) => a.sort_order - b.sort_order); inZone.forEach((row, index) => position.set(row.id, { up: index > 0, down: index < inZone.length - 1 })); }
  const canReorder = filter === "all" && (user.role === "kierownik" || user.role === "brygadzista");
  return <><section className="operational-toolbar card"><label>Strefa<select value={zoneId} onChange={e => setZoneId(e.target.value)}><option value="">Wszystkie strefy</option>{zones.map(zone => <option key={zone.id} value={zone.id}>{zone.name}</option>)}</select></label><label>Status<select value={filter} onChange={e => setFilter(e.target.value)}><option value="all">Wszystkie</option><option value="todo">Do zrobienia</option><option value="built">Zbudowane, bez QA/QC</option><option value="qc">Sprawdzone QA/QC</option></select></label><div className="operational-kpis"><span><b>{rows.length}</b> rzędów</span><span><b>{built}</b> zbudowanych</span><span><b>{qc}</b> sprawdzonych</span></div>{filter !== "all" && <small className="sorting-hint">Wybierz „Wszystkie”, aby zmieniać kolejność rzędów.</small>}</section><div className="operational-list">{visible.map(row => <OperationalRowCard key={row.id} row={row} user={user} onUpdate={update} onMove={move} canMoveUp={position.get(row.id)?.up} canMoveDown={position.get(row.id)?.down} canReorder={canReorder} notify={notify} />)}</div>{!visible.length && <Empty>{rows.length ? "Brak rzędów spełniających wybrany filtr." : "Skonfiguruj liczbę rzędów w strefie, aby wygenerować widok operacyjny."}</Empty>}</>;
}

function TrackerConfiguration({ project, sync, notify, user }) {
  const [view, setView] = useState("zones");
  if (!project) return <Empty>Wybierz aktywny projekt.</Empty>;
  return <><PageHead eyebrow="STREFY I AUTOMATYCZNE RZĘDY" title={view === "zones" ? "Konfiguracja budowy" : "Widok operacyjny rzędów"}><div className="view-switch"><button className={view === "zones" ? "active" : ""} onClick={() => setView("zones")}>Konfiguracja stref</button><button className={view === "rows" ? "active" : ""} onClick={() => setView("rows")}>Rzędy operacyjne</button></div></PageHead>{view === "zones" ? <ZoneConfigurationView project={project} sync={sync} notify={notify} user={user} onOpenRows={() => setView("rows")} /> : <OperationalRowsView project={project} sync={sync} notify={notify} user={user} />}</>;
}

function ProjectDemand({ project, sync, notify }) {
  const [data, setData] = useState(null);
  const load = useCallback(async () => { if (!project) return; try { setData(await cachedGet(`/api/projects/${project.id}/tracker-config`)); } catch (e) { notify(e.message, "error"); } }, [project, sync]);
  useEffect(() => { load(); }, [load]);
  const groups = useMemo(() => { const result = {}; for (const item of data?.grand_total || []) (result[item.category] ||= []).push(item); return result; }, [data]);
  if (!project) return <Empty>Wybierz aktywny projekt.</Empty>; if (!data) return <Loader />;
  return <><PageHead eyebrow="BOM PROJEKTOWY" title="Zapotrzebowanie materiałowe"><span className="badge neutral">bez stanów magazynowych i dostaw</span></PageHead><section className="demand-summary"><article className="card"><small>Łącznie rzędów</small><strong>{data.total_rows}</strong></article><article className="card"><small>Łącznie modułów</small><strong>{data.total_modules}</strong></article><article className="card wide"><small>Skonfigurowane warianty</small><div>{data.variants.map(item => <span key={item.code}>{item.code} <b>{item.row_count}</b></span>)}</div></article></section><ModuleReference demand={data} /><section className="card demand-policy"><strong>Podstawa obliczeń</strong><p>{data.policy}</p></section>{!data.total_rows ? <Empty>Najpierw wpisz liczbę rzędów w module Strefy i rzędy.</Empty> : <section className="demand-groups">{Object.entries(groups).map(([category, items], index) => <details className="card demand-group" open={index === 0} key={category}><summary><span>{category}</span><b>{items.length} pozycji</b></summary><DemandTable items={items} /></details>)}</section>}<section className="card variant-breakdown"><div className="card-head"><div><p className="eyebrow">KONTROLA OBLICZEŃ</p><h2>Zapotrzebowanie według wariantu</h2></div></div>{data.variants.filter(item => item.row_count > 0).map(item => <details key={item.code}><summary><strong>{item.row_count} × {item.code}</strong><span>{item.total_modules} modułów · {item.per_row.length} pozycji</span></summary><VariantBomTable items={item.per_row} rowCount={item.row_count} /></details>)}</section></>;
}

function RowEditor({ row, templates, materials, sectionArchived, user, action, remove, notify }) {
  const [open, setOpen] = useState(false); const [photoRefresh, setPhotoRefresh] = useState(0);
  const [form, setForm] = useState({ code: row.code, template_id: row.template_id || "", variant_name: row.variant_name || "", length_m: row.length_m || 0, specification: row.specification || "", material_quantities: { ...emptyMaterials(), ...(row.material_quantities || {}) }, note: row.note || "" });
  useEffect(() => setForm({ code: row.code, template_id: row.template_id || "", variant_name: row.variant_name || "", length_m: row.length_m || 0, specification: row.specification || "", material_quantities: { ...emptyMaterials(), ...(row.material_quantities || {}) }, note: row.note || "" }), [row]);
  function selectTemplate(id) { const template = templates.find(x => x.id === Number(id)); setForm(current => template ? { ...current, template_id: id, variant_name: template.name, length_m: template.default_length_m, specification: template.specification, material_quantities: { ...emptyMaterials(), ...template.materials } } : { ...current, template_id: "" }); }
  async function photo(file) { if (!file) return; const fd = new FormData(); fd.append("file", file); try { await upload(`/api/row/${row.id}/photos`, fd); notify("Zdjęcie przypisane do rzędu"); setPhotoRefresh(x => x + 1); } catch (e) { notify(e.message, "error"); } }
  return <article className={`construction-row-v3 ${row.qc_checked ? "verified" : row.built ? "built" : ""}`}><div className="row-summary"><button className="row-expand" onClick={() => setOpen(x => !x)}><strong>{row.code}</strong><small>{row.variant_name || "wariant własny"} · {row.length_m ? `${row.length_m} m` : "długość własna"}</small></button><button className={`status-button ${row.built ? "done" : ""}`} disabled={sectionArchived} onClick={() => action(row.id, { built: !row.built }, row.built ? "Cofnięto wykonanie" : "Rząd zbudowany")}><span>{row.built ? "✓" : "○"}</span><div>{row.built ? "Zbudowany" : "Do zrobienia"}<small>{row.built_by || ""}</small></div></button><button className={`status-button ${row.qc_checked ? "qc" : ""}`} disabled={user.role !== "kierownik" || !row.built || sectionArchived} onClick={() => action(row.id, { qc_checked: !row.qc_checked }, row.qc_checked ? "Cofnięto QC" : "QC odebrane")}><span>{row.qc_checked ? "✓" : "○"}</span><div>{row.qc_checked ? "QA/QC OK" : "Oczekuje QC"}<small>{row.qc_by || ""}</small></div></button><label className="mini-camera">▧<input type="file" accept="image/*" capture="environment" onChange={e => photo(e.target.files[0])} /></label></div>{open && <div className="row-editor"><div className="form-grid"><label>Oznaczenie<input value={form.code} onChange={e => setForm({ ...form, code: e.target.value })} /></label><label>Szablon (opcjonalny)<select value={form.template_id} onChange={e => selectTemplate(e.target.value)}><option value="">Konfiguracja własna</option>{templates.map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Wariant / układ<input placeholder="np. 1x28, nietypowy" value={form.variant_name} onChange={e => setForm({ ...form, variant_name: e.target.value })} /></label><label>Długość [m]<input type="number" min="0" step="0.001" value={form.length_m} onChange={e => setForm({ ...form, length_m: e.target.value })} /></label></div><label>Specyfikacja własna<textarea value={form.specification} onChange={e => setForm({ ...form, specification: e.target.value })} placeholder="Dowolne parametry, modyfikacje i uwagi techniczne" /></label><div className="three-materials">{materials.map(item => <label key={item.slot_number}>{item.name} / rząd<input type="number" min="0" step="0.01" value={form.material_quantities[String(item.slot_number)] || 0} onChange={e => setForm({ ...form, material_quantities: { ...form.material_quantities, [item.slot_number]: Number(e.target.value) } })} /></label>)}</div><label>Notatka do rzędu<textarea value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} /></label><div className="card-actions"><button className="primary" onClick={() => action(row.id, { ...form, template_id: Number(form.template_id) || null, length_m: Number(form.length_m) }, "Rząd zaktualizowany")}>Zapisz cały rząd</button>{user.role === "kierownik" && <button className="danger-button" onClick={() => remove(row)}>Usuń rząd</button>}</div><PhotoGallery entityType="row" entityId={row.id} refresh={photoRefresh} notify={notify} /></div>}</article>;
}

function Structure({ project, sync, notify, user, navigate }) {
  const [tree, setTree] = useState(null); const [templates, setTemplates] = useState([]); const [materials, setMaterials] = useState([]); const [selected, setSelected] = useState(null);
  const [zoneName, setZoneName] = useState(""); const [sectionForm, setSectionForm] = useState({ zone_id: "", name: "" });
  const [rowForm, setRowForm] = useState({ code: "", template_id: "", variant_name: "", length_m: "", specification: "", material_quantities: emptyMaterials() });
  const load = useCallback(async () => { if (!project) return; try { const [a, b, c] = await Promise.all([cachedGet(`/api/projects/${project.id}/tree`), cachedGet(`/api/material-templates?project_id=${project.id}`), cachedGet(`/api/projects/${project.id}/materials`)]); setTree(a); setTemplates(b); setMaterials(c); if (!selected) setSelected(a.zones.flatMap(z => z.sections)[0]?.id); } catch (e) { notify(e.message, "error"); } }, [project, sync]);
  useEffect(() => { load(); }, [load]);
  const sections = tree?.zones.flatMap(zone => zone.sections.map(section => ({ ...section, zoneName: zone.name }))) || []; const section = sections.find(x => x.id === selected) || sections[0];
  async function action(path, method, body, message) { try { const result = await mutate(path, method, body); notify(result.queued ? "Zapisano offline — oczekuje na synchronizację" : message); if (!result.queued) load(); } catch (e) { notify(e.message, "error"); } }
  function chooseTemplate(id) { const t = templates.find(x => x.id === Number(id)); setRowForm(x => t ? { ...x, template_id: id, variant_name: t.name, length_m: t.default_length_m, specification: t.specification, material_quantities: { ...emptyMaterials(), ...t.materials } } : { ...x, template_id: "" }); }
  async function addRow(e) { e.preventDefault(); if (!section) return; await action("/api/rows", "POST", { ...rowForm, section_id: section.id, template_id: Number(rowForm.template_id) || null, length_m: Number(rowForm.length_m || 0) }, "Rząd dodany"); setRowForm({ code: "", template_id: "", variant_name: "", length_m: "", specification: "", material_quantities: emptyMaterials() }); }
  async function removeRow(row) { if (window.confirm(`Usunąć rząd ${row.code}?`)) await action(`/api/rows/${row.id}`, "DELETE", {}, "Rząd usunięty"); }
  if (!project) return <Empty>Wybierz aktywny projekt.</Empty>; if (!tree) return <Loader />;
  return <><PageHead eyebrow="ELASTYCZNA STRUKTURA" title="Sekcje i rzędy"><span className="badge neutral">każdy rząd edytowalny</span></PageHead><div className="structure-layout"><aside className="tree-panel card"><h3>Strefy i sekcje</h3>{tree.zones.map(zone => <div className="tree-zone" key={zone.id}><strong>{zone.name}</strong>{zone.sections.map(item => <button className={section?.id === item.id ? "active" : ""} onClick={() => setSelected(item.id)} key={item.id}><span>{item.name}</span><small>{item.rows.length}</small></button>)}</div>)}{user.role === "kierownik" && <details className="inline-add"><summary>+ Strefa lub sekcja</summary><form onSubmit={e => { e.preventDefault(); action("/api/zones", "POST", { project_id: project.id, name: zoneName }, "Strefa dodana"); setZoneName(""); }}><input required placeholder="Nazwa strefy" value={zoneName} onChange={e => setZoneName(e.target.value)} /><button>Dodaj strefę</button></form><form onSubmit={e => { e.preventDefault(); action("/api/sections", "POST", { zone_id: Number(sectionForm.zone_id), name: sectionForm.name }, "Sekcja dodana"); setSectionForm({ zone_id: "", name: "" }); }}><select required value={sectionForm.zone_id} onChange={e => setSectionForm({ ...sectionForm, zone_id: e.target.value })}><option value="">Wybierz strefę</option>{tree.zones.map(z => <option key={z.id} value={z.id}>{z.name}</option>)}</select><input required placeholder="Własna nazwa sekcji" value={sectionForm.name} onChange={e => setSectionForm({ ...sectionForm, name: e.target.value })} /><button>Dodaj sekcję</button></form></details>}</aside><section className="work-panel">{!section ? <Empty>Dodaj strefę i sekcję.</Empty> : <><div className="section-summary card"><div><p className="eyebrow">{section.zoneName}</p><h2>{section.name}</h2><small>{section.rows.filter(x => x.built).length}/{section.rows.length} zbudowanych</small></div><div className="summary-progress"><strong>{pct(section.rows.filter(x => x.built).length, section.rows.length)}%</strong><Progress value={pct(section.rows.filter(x => x.built).length, section.rows.length)} /></div>{user.role === "kierownik" && <div className="card-actions"><button onClick={() => { const name = window.prompt("Nowa nazwa sekcji", section.name); if (name) action(`/api/sections/${section.id}`, "PATCH", { name }, "Nazwa zmieniona"); }}>Zmień nazwę</button><button className="secondary" disabled={section.archived} onClick={() => action(`/api/sections/${section.id}/archive`, "POST", {}, "Sekcja zarchiwizowana")}>Archiwizuj</button><button className="danger-button" onClick={() => window.confirm("Usunąć sekcję i wszystkie rzędy?") && action(`/api/sections/${section.id}`, "DELETE", {}, "Sekcja usunięta")}>Usuń</button></div>}</div><details className="card add-row-card" open={!section.rows.length}><summary>+ Dodaj pojedynczy rząd z własnymi parametrami</summary><form onSubmit={addRow}><div className="form-grid four"><label>Oznaczenie<input required placeholder="np. R-001" value={rowForm.code} onChange={e => setRowForm({ ...rowForm, code: e.target.value })} /></label><label>Szablon<select value={rowForm.template_id} onChange={e => chooseTemplate(e.target.value)}><option value="">Bez szablonu</option>{templates.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select></label><label>Wariant / układ<input placeholder="np. 1x28" value={rowForm.variant_name} onChange={e => setRowForm({ ...rowForm, variant_name: e.target.value })} /></label><label>Długość [m]<input type="number" min="0" step="0.001" value={rowForm.length_m} onChange={e => setRowForm({ ...rowForm, length_m: e.target.value })} /></label></div><label>Własna specyfikacja<textarea value={rowForm.specification} onChange={e => setRowForm({ ...rowForm, specification: e.target.value })} /></label><div className="three-materials">{materials.map(item => <label key={item.slot_number}>{item.name} / rząd<input type="number" min="0" step="0.01" value={rowForm.material_quantities[String(item.slot_number)] || 0} onChange={e => setRowForm({ ...rowForm, material_quantities: { ...rowForm.material_quantities, [item.slot_number]: Number(e.target.value) } })} /></label>)}</div><button className="primary">Dodaj rząd</button></form></details><div className="row-list-v3">{section.rows.map(row => <RowEditor key={row.id} row={row} templates={templates} materials={materials} sectionArchived={section.archived} user={user} notify={notify} action={(id, body, msg) => action(`/api/rows/${id}`, "PATCH", body, msg)} remove={removeRow} />)}</div>{!section.rows.length && <Empty>Dodaj pierwszy rząd. Każdy kolejny może mieć inną długość, wariant i ilości.</Empty>}</>}</section></div></>;
}

function Calculator({ project, sync, notify, user }) {
  const [templates, setTemplates] = useState([]); const [slots, setSlots] = useState([]); const [selected, setSelected] = useState(""); const [result, setResult] = useState(null);
  const blank = { name: "", structure_type: project?.structure_type || "", default_length_m: 0, specification: "", materials: emptyMaterials(), row_count: 1 };
  const [form, setForm] = useState(blank);
  const load = useCallback(async () => { if (!project) return; try { const [a, b] = await Promise.all([cachedGet(`/api/material-templates?project_id=${project.id}`), cachedGet(`/api/projects/${project.id}/materials`)]); setTemplates(a); setSlots(b); } catch (e) { notify(e.message, "error"); } }, [project, sync]);
  useEffect(() => { setForm({ ...blank, structure_type: project?.structure_type || "" }); setSelected(""); setResult(null); load(); }, [project?.id, sync]);
  function choose(id) { setSelected(id); const item = templates.find(x => x.id === Number(id)); setForm(item ? { name: item.name, structure_type: item.structure_type, default_length_m: item.default_length_m, specification: item.specification, materials: { ...emptyMaterials(), ...item.materials }, row_count: form.row_count } : { ...blank, structure_type: project?.structure_type || "", row_count: form.row_count }); }
  async function saveTemplate() { try { const body = { project_id: project.id, name: form.name, structure_type: form.structure_type, default_length_m: Number(form.default_length_m), specification: form.specification, materials: form.materials }; const item = selected ? await api(`/api/material-templates/${selected}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }) : await api("/api/material-templates", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); notify("Szablon zapamiętany"); setSelected(item.id); load(); } catch (e) { notify(e.message, "error"); } }
  async function calculate() { try { setResult(await api("/api/calculator", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ project_id: project.id, template_id: Number(selected) || null, variant_name: form.name, length_m: Number(form.default_length_m), row_count: Number(form.row_count), materials: form.materials }) })); } catch (e) { notify(e.message, "error"); } }
  async function removeTemplate() { if (!selected || !window.confirm("Usunąć ten szablon?")) return; try { await api(`/api/material-templates/${selected}`, { method: "DELETE" }); notify("Szablon usunięty"); choose(""); load(); } catch (e) { notify(e.message, "error"); } }
  if (!project) return <Empty>Wybierz projekt.</Empty>;
  return <><PageHead eyebrow="WARIANTY Z PIĘCIU PLIKÓW" title="Kalkulator materiałowy"><span className="badge success">1x28 · 1x42 · 1x56 · 1x70</span></PageHead><div className="calculator-layout"><section className="card calculator-form"><label>Zapisane konfiguracje<select value={selected} onChange={e => choose(e.target.value)}><option value="">Nowa konfiguracja własna</option>{templates.map(item => <option key={item.id} value={item.id}>{item.name}{item.source_based ? " · źródło" : ""}</option>)}</select></label>{templates.find(x => x.id === Number(selected))?.source_based && <div className="source-template-note">✓ Ilości startowe pochodzą z zatwierdzonego manuala i BOM. Każde pole nadal możesz skorygować.</div>}<label>Nazwa wariantu<input placeholder="np. 1x28 albo układ specjalny" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label><label>Typ struktury<input value={form.structure_type} onChange={e => setForm({ ...form, structure_type: e.target.value })} /></label><label>Długość referencyjna [m]<input type="number" min="0" step="0.001" value={form.default_length_m} onChange={e => setForm({ ...form, default_length_m: e.target.value })} /></label><label>Specyfikacja<textarea value={form.specification} onChange={e => setForm({ ...form, specification: e.target.value })} /></label><div className="three-materials vertical">{slots.map(item => <label key={item.slot_number}>{item.name} na jeden rząd<input type="number" min="0" step="0.01" value={form.materials[String(item.slot_number)] || 0} onChange={e => setForm({ ...form, materials: { ...form.materials, [item.slot_number]: Number(e.target.value) } })} /></label>)}</div><label>Liczba rzędów do obliczenia<input type="number" min="1" value={form.row_count} onChange={e => setForm({ ...form, row_count: e.target.value })} /></label><button className="primary wide" onClick={calculate}>Przelicz ręczne ilości</button><button className="secondary wide" disabled={!form.name} onClick={saveTemplate}>{selected ? "Zapisz zmiany w szablonie" : "Zapamiętaj jako szablon"}</button>{selected && user.role === "kierownik" && <button className="danger-button wide" onClick={removeTemplate}>Usuń szablon</button>}</section><section className="calculator-results">{!result ? <div className="card result-placeholder"><span>⌗</span><h2>Wybierz wariant z dokumentacji</h2><p>Szablony 1x28, 1x42, 1x56 i 1x70 zawierają liczby rur, płatwi oraz kompletów mocowań z zatwierdzonych tabel. Wszystkie wartości możesz ręcznie zmienić.</p></div> : <><div className="result-banner"><div><p className="eyebrow">WYNIK</p><h2>{result.input.row_count} × {result.variant_name}</h2></div><div><small>Długość wpisana</small><strong>{result.input.length_m} m</strong></div></div><div className="card"><div className="three-result">{result.materials.map(item => <div key={item.material_id}><span>{item.slot_number}</span><div><strong>{item.name}</strong><small>{item.per_row} {item.unit} / rząd</small></div><b>{item.total} {item.unit}</b></div>)}</div><p className="hint">{result.assumption}</p></div></>}</section></div></>;
}

function Logistics({ project, sync, notify, user }) {
  const [materials, setMaterials] = useState([]); const [stock, setStock] = useState([]); const [deliveries, setDeliveries] = useState([]); const [demand, setDemand] = useState([]);
  const [delivery, setDelivery] = useState({ delivery_date: today(), wz_number: "", supplier: "", note: "", quantities: emptyMaterials(), damaged: emptyMaterials() });
  const load = useCallback(async () => { if (!project) return; try { const [a, b, c] = await Promise.all([cachedGet(`/api/projects/${project.id}/materials`), cachedGet(`/api/logistics/stock?project_id=${project.id}`), cachedGet(`/api/deliveries?project_id=${project.id}`)]); setMaterials(a); setDemand(a.map(x => ({ ...x }))); setStock(b); setDeliveries(c); } catch (e) { notify(e.message, "error"); } }, [project, sync]);
  useEffect(() => { load(); }, [load]);
  function updateDemand(index, key, value) { setDemand(demand.map((item, i) => i === index ? { ...item, [key]: value } : item)); }
  async function saveDemand() { try { await api(`/api/projects/${project.id}/materials`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ items: demand.map(x => ({ slot_number: x.slot_number, name: x.name, unit: x.unit, required_quantity: Number(x.required_quantity || 0) })) }) }); notify("Zapotrzebowanie zapisane"); load(); } catch (e) { notify(e.message, "error"); } }
  async function saveDelivery(e) { e.preventDefault(); const items = materials.map(item => ({ material_id: item.id, quantity_received: Number(delivery.quantities[item.slot_number] || 0), quantity_damaged: Number(delivery.damaged[item.slot_number] || 0) })).filter(x => x.quantity_received > 0); if (!items.length) return notify("Wpisz ilość przynajmniej jednej części", "error"); try { const result = await mutate("/api/deliveries", "POST", { project_id: project.id, delivery_date: delivery.delivery_date, wz_number: delivery.wz_number, supplier: delivery.supplier, note: delivery.note, client_id: uid(), items }); notify(result.queued ? "WZ zapisane offline" : "Dostawa doliczona do stanu pola"); setDelivery({ delivery_date: today(), wz_number: "", supplier: "", note: "", quantities: emptyMaterials(), damaged: emptyMaterials() }); if (!result.queued) load(); } catch (err) { notify(err.message, "error"); } }
  if (!project) return <Empty>Wybierz projekt.</Empty>;
  return <><PageHead eyebrow="MAGAZYN A POLE" title="Zapotrzebowanie i fizyczne dostawy"><span className="badge neutral">dokładnie 3 części</span></PageHead><div className="logistics-explainer"><div><strong>1. Zapotrzebowanie projektu</strong><span>Ile potrzeba łącznie</span></div><i>→</i><div><strong>2. Dostawy WZ</strong><span>Co rzeczywiście przyjechało</span></div><i>→</i><div><strong>3. Stan na polu</strong><span>Dostawy minus uszkodzenia</span></div></div><section className="stock-cards">{stock.map(item => <article className="card" key={item.material_id}><span className="material-number">{item.slot_number}</span><h2>{item.name}</h2><div className="stock-values"><div><small>Potrzeba</small><strong>{item.required} {item.unit}</strong></div><div><small>Na polu</small><strong>{item.available} {item.unit}</strong></div></div><Progress value={item.required ? item.available / item.required * 100 : 0} /><span className={`balance ${item.balance < 0 ? "negative" : "positive"}`}>{item.balance < 0 ? `Brakuje ${Math.abs(item.balance)}` : `Nadwyżka ${item.balance}`} {item.unit}</span></article>)}</section><div className="split"><section className="card"><div className="card-head"><div><p className="eyebrow">LISTA PROJEKTOWA</p><h2>Edytuj trzy części i zapotrzebowanie</h2></div></div>{demand.map((item, index) => <div className="demand-line" key={item.slot_number}><span>{item.slot_number}</span><input aria-label="Nazwa części" value={item.name} onChange={e => updateDemand(index, "name", e.target.value)} /><input aria-label="Jednostka" value={item.unit} onChange={e => updateDemand(index, "unit", e.target.value)} /><input aria-label="Zapotrzebowanie" type="number" min="0" step="0.01" value={item.required_quantity} onChange={e => updateDemand(index, "required_quantity", e.target.value)} /></div>)}{(user.role === "kierownik" || user.role === "magazynier") && <button className="primary wide" onClick={saveDemand}>Zapisz zapotrzebowanie</button>}</section>{(user.role === "kierownik" || user.role === "magazynier") && <form className="card" onSubmit={saveDelivery}><div className="card-head"><div><p className="eyebrow">FIZYCZNA DOSTAWA</p><h2>Nowy dokument WZ</h2></div></div><div className="form-grid"><label>Data<input type="date" value={delivery.delivery_date} onChange={e => setDelivery({ ...delivery, delivery_date: e.target.value })} /></label><label>Numer WZ<input required value={delivery.wz_number} onChange={e => setDelivery({ ...delivery, wz_number: e.target.value })} /></label><label>Dostawca<input value={delivery.supplier} onChange={e => setDelivery({ ...delivery, supplier: e.target.value })} /></label></div>{materials.map(item => <div className="delivery-three" key={item.id}><strong>{item.name}</strong><label>Przyjechało<input type="number" min="0" step="0.01" value={delivery.quantities[item.slot_number] || 0} onChange={e => setDelivery({ ...delivery, quantities: { ...delivery.quantities, [item.slot_number]: e.target.value } })} /></label><label>Uszkodzone<input type="number" min="0" step="0.01" value={delivery.damaged[item.slot_number] || 0} onChange={e => setDelivery({ ...delivery, damaged: { ...delivery.damaged, [item.slot_number]: e.target.value } })} /></label></div>)}<label>Uwagi<textarea value={delivery.note} onChange={e => setDelivery({ ...delivery, note: e.target.value })} /></label><button className="primary wide">Dodaj dostawę do stanu pola</button></form>}</div><section className="card"><div className="card-head"><h2>Historia fizycznych dostaw</h2></div>{deliveries.map(item => <details className="delivery" key={item.id}><summary><div><strong>WZ {item.wz_number}</strong><small>{item.supplier || "bez dostawcy"}</small></div><span>{fmt(item.delivery_date)}</span></summary>{item.items.map(line => <div className="delivery-line" key={line.material_id}><span>{line.name}</span><strong>{line.quantity_received} {line.unit}</strong>{line.quantity_damaged > 0 && <em>uszkodzone {line.quantity_damaged}</em>}</div>)}</details>)}{!deliveries.length && <Empty>Stan pola wynosi 0. Dodaj pierwszy dokument WZ.</Empty>}</section></>;
}

function Reports({ project, sync, notify, user }) {
  const blank = { work_date: today(), team: "Brygada 1", stage: "", people: 1, hours: 8, rows_completed: 0, qc_notes: "", note: "", row_id: "" };
  const [logs, setLogs] = useState([]); const [tree, setTree] = useState(null); const [form, setForm] = useState(blank); const [photo, setPhoto] = useState(null); const [editing, setEditing] = useState(null); const [photoRefresh, setPhotoRefresh] = useState(0); const [reportDate, setReportDate] = useState(today());
  const load = useCallback(async () => { if (!project) return; try { const [a, b] = await Promise.all([cachedGet(`/api/worklogs?project_id=${project.id}`), cachedGet(`/api/projects/${project.id}/tree`)]); setLogs(a); setTree(b); } catch (e) { notify(e.message, "error"); } }, [project, sync]);
  useEffect(() => { load(); }, [load]);
  const rows = tree?.zones.flatMap(z => z.sections.flatMap(s => s.rows.map(r => ({ ...r, label: `${z.name} / ${s.name} / ${r.code}` })))) || [];
  async function submit(e) { e.preventDefault(); const body = { ...form, project_id: project.id, people: Number(form.people), hours: Number(form.hours), rows_completed: Number(form.rows_completed), row_id: Number(form.row_id) || null, client_id: editing ? undefined : uid() }; try { let id = editing; if (editing) await api(`/api/worklogs/${editing}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); else { const result = await mutate("/api/worklogs", "POST", body); if (result.queued) { notify(photo ? "Meldunek zapisany offline; zdjęcie dodaj po synchronizacji" : "Meldunek zapisany offline"); setForm(blank); return; } id = result.id; } if (photo) { const fd = new FormData(); fd.append("file", photo); await upload(`/api/worklog/${id}/photos`, fd); } notify(editing ? "Meldunek zaktualizowany" : "Meldunek wysłany"); setEditing(null); setForm(blank); setPhoto(null); setPhotoRefresh(x => x + 1); load(); } catch (err) { notify(err.message, "error"); } }
  function edit(item) { setEditing(item.id); setForm({ work_date: item.work_date, team: item.team, stage: item.stage, people: item.people, hours: item.hours, rows_completed: item.rows_completed, qc_notes: item.qc_notes || "", note: item.note || "", row_id: item.row_id || "" }); window.scrollTo({ top: 0, behavior: "smooth" }); }
  async function remove(id) { if (!window.confirm("Usunąć meldunek?")) return; try { await api(`/api/worklogs/${id}`, { method: "DELETE" }); notify("Meldunek usunięty"); load(); } catch (e) { notify(e.message, "error"); } }
  if (!project) return <Empty>Wybierz projekt.</Empty>;
  return <><PageHead eyebrow="SZYBKI MELDUNEK Z TELEFONU" title="Praca i dziennik jakości"><button className="secondary" onClick={() => download(`/api/reports/daily?project_id=${project.id}&report_date=${reportDate}`, `ASOLAR-raport-${reportDate}.pdf`).catch(e => notify(e.message, "error"))}>↓ Raport PDF</button></PageHead><div className="report-date"><label>Data PDF<input type="date" value={reportDate} onChange={e => setReportDate(e.target.value)} /></label></div><div className="split report-layout"><form className="card report-mobile-form" onSubmit={submit}><div className="card-head"><h2>{editing ? "Edytuj meldunek" : "Nowy meldunek dzienny"}</h2>{editing && <button type="button" className="text-button" onClick={() => { setEditing(null); setForm(blank); }}>Anuluj</button>}</div><div className="form-grid"><label>Data<input type="date" value={form.work_date} onChange={e => setForm({ ...form, work_date: e.target.value })} /></label><label>Brygada<input value={form.team} onChange={e => setForm({ ...form, team: e.target.value })} /></label><label>Rząd (opcjonalnie)<select value={form.row_id} onChange={e => setForm({ ...form, row_id: e.target.value })}><option value="">Meldunek ogólny</option>{rows.map(row => <option key={row.id} value={row.id}>{row.label}</option>)}</select></label></div><label>Dowolny opis wykonanych prac<textarea required rows="3" placeholder="Wpisz własny etap, modyfikację lub nietypowe zadanie…" value={form.stage} onChange={e => setForm({ ...form, stage: e.target.value })} /></label><div className="mobile-number-grid"><label>Rzędy zbudowane<input type="number" min="0" step="0.1" value={form.rows_completed} onChange={e => setForm({ ...form, rows_completed: e.target.value })} /></label><label>Osoby w ekipie<input type="number" min="1" value={form.people} onChange={e => setForm({ ...form, people: e.target.value })} /></label><label>Godziny / osoba<input type="number" min="0.5" step="0.5" value={form.hours} onChange={e => setForm({ ...form, hours: e.target.value })} /></label></div><label>Dziennik QA/QC — swobodne notatki<textarea rows="4" placeholder="Kontrole, pomiary, niezgodności, poprawki…" value={form.qc_notes} onChange={e => setForm({ ...form, qc_notes: e.target.value })} /></label><label>Pozostałe uwagi<textarea value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} /></label><label className="camera-button"><input type="file" accept="image/*" capture="environment" onChange={e => setPhoto(e.target.files[0])} /><span>▧</span>{photo ? photo.name : "Zrób zdjęcie aparatem"}</label><button className="primary wide">{editing ? "Zapisz meldunek" : "Wyślij meldunek"}</button></form><section className="report-history">{logs.map(item => <article className="card report-entry" key={item.id}><div className="card-head"><div><p className="eyebrow">{fmt(item.work_date)} · {item.team}</p><h2>{item.rows_completed} rzędów · {item.people} osób · {item.manhours} rbh</h2></div><span className="badge neutral">▧ {item.photos}</span></div><strong>Wykonane prace</strong><p>{item.stage}</p>{item.qc_notes && <div className="qc-journal"><strong>QA/QC</strong><p>{item.qc_notes}</p></div>}{item.note && <p className="muted-note">{item.note}</p>}<PhotoGallery entityType="worklog" entityId={item.id} refresh={photoRefresh} notify={notify} /><div className="card-actions"><button onClick={() => edit(item)}>Edytuj</button>{user.role === "kierownik" && <button className="danger-button" onClick={() => remove(item.id)}>Usuń</button>}</div></article>)}{!logs.length && <Empty>Brak meldunków. Formularz jest gotowy do użycia na telefonie.</Empty>}</section></div></>;
}

function DocumentsLegacy({ project, sync, notify }) {
  const [docs, setDocs] = useState([]); const [instructions, setInstructions] = useState([]); const [basis, setBasis] = useState(null); const [file, setFile] = useState(null); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => { if (!project) return; try { const [a, b, c] = await Promise.all([cachedGet(`/api/documents?project_id=${project.id}`), cachedGet(`/api/instructions?project_id=${project.id}`), cachedGet(`/api/source-basis?project_id=${project.id}`)]); setDocs(a); setInstructions(b); setBasis(c); } catch (e) { notify(e.message, "error"); } }, [project, sync]); useEffect(() => { load(); }, [load]);
  async function submit(e) { e.preventDefault(); if (!file) return; setBusy(true); const fd = new FormData(); fd.append("project_id", project.id); fd.append("file", file); try { await upload("/api/documents", fd); notify("Dokument wgrany i przeanalizowany"); setFile(null); e.target.reset(); load(); } catch (err) { notify(err.message, "error"); } finally { setBusy(false); } }
  if (!project) return <Empty>Wybierz projekt.</Empty>;
  return <><PageHead eyebrow="TYLKO ZATWIERDZONE DOKUMENTY" title="Baza źródłowa i instrukcje"><span className="badge success">{basis?.registered_sources || 0}/{basis?.expected_sources || 8} źródeł</span></PageHead>{basis && <section className="source-hero card"><div><p className="eyebrow">JEDYNA BAZA DANYCH TECHNICZNYCH</p><h2>{basis.project.name} · {basis.project.capacity_mw} MWp</h2><p>{basis.policy}</p><small>{basis.project.location}</small></div><div className="source-variants">{basis.templates.map(item => <span key={item.name}>{item.name}</span>)}</div></section>}<div className="source-grid"><section className="card"><div className="card-head"><div><p className="eyebrow">{basis?.expected_sources || 8} PLIKÓW W PACZCE</p><h2>Zatwierdzone źródła</h2></div></div>{docs.filter(doc => doc.approved_source).map(doc => <div className="document source-document" key={doc.id}><div className={`file-type ${doc.kind.toLowerCase()}`}>{doc.kind}</div><div><strong>{doc.filename}</strong><small>{doc.role}</small><span className="source-hash">SHA-256 {doc.sha256?.slice(0, 12)}…</span></div><button className="icon-button" title="Pobierz oryginalny plik" onClick={() => download(`/api/documents/${doc.id}/file`, doc.filename)}>↓</button></div>)}</section><section className="card source-summary"><div><p className="eyebrow">ZAKRES MECHANICZNY</p><h2>Co program wykorzystuje</h2></div><div className="scope-columns"><div><strong>Uwzględnione</strong>{basis?.scope.included.map(item => <span key={item}>✓ {item}</span>)}</div><div><strong>Poza zakresem</strong>{basis?.scope.excluded.map(item => <span key={item}>— {item}</span>)}</div></div></section></div><section className="card instruction-panel"><div className="card-head"><div><p className="eyebrow">KROK PO KROKU</p><h2>Instrukcje montażu konstrukcji</h2></div><span className="badge neutral">{instructions.length} etapów</span></div>{instructions.map((item, i) => <details className="instruction source-instruction" key={`${item.document_id}-${i}`} open={i === 0}><summary><span>{item.section || i + 1}</span><strong>{item.title}</strong><small>str. {item.pages}</small></summary><ol>{item.steps?.map((step, index) => <li key={index}>{step}</li>)}</ol>{item.quality && <div className="quality-note"><strong>Kontrola:</strong> {item.quality}</div>}<small>Źródło: {item.source}, strony {item.pages}</small></details>)}</section>{basis && <div className="split source-reference"><section className="card"><div className="card-head"><div><p className="eyebrow">TABELA 2</p><h2>Narzędzia</h2></div></div><ul className="tool-list">{basis.tools.items.map(item => <li key={item}>{item}</li>)}</ul><small>{basis.tools.source}</small></section><section className="card"><div className="card-head"><div><p className="eyebrow">MOMENTY Z MANUALA</p><h2>Połączenia kontrolne</h2></div></div><div className="torque-list">{basis.torques.map(item => <div key={item.item}><span>{item.item}<small>{item.source}</small></span><strong>{item.min_nm}–{item.max_nm} N·m</strong></div>)}</div></section></div>}<section className="upload-card supplemental-upload"><div className="upload-icon">⇧</div><div><h2>Dodaj plik pomocniczy</h2><p>Plik będzie dostępny w projekcie, lecz nie zmieni instrukcji, wariantów ani bazy BOM, jeśli nie jest jednym z ośmiu zatwierdzonych źródeł.</p></div><form onSubmit={submit}><label className="file-drop"><input type="file" accept=".pdf,.dwg,.dxf,.xlsx,.xlsm" onChange={e => setFile(e.target.files[0])} /><span>{file?.name || "Wybierz plik"}</span></label><button className="primary" disabled={busy}>{busy ? "Zapisywanie…" : "Dodaj"}</button></form></section>{docs.some(doc => !doc.approved_source) && <section className="card"><h2>Pliki pomocnicze</h2>{docs.filter(doc => !doc.approved_source).map(doc => <div className="document" key={doc.id}><div className={`file-type ${doc.kind.toLowerCase()}`}>{doc.kind}</div><div><strong>{doc.filename}</strong><small>{fmt(doc.uploaded_at)}</small><span className="badge neutral">{doc.status}</span></div><button className="icon-button" onClick={() => download(`/api/documents/${doc.id}/file`, doc.filename)}>↓</button></div>)}</section>}</>;
}

function Documents({ project, sync, notify }) {
  const [docs, setDocs] = useState([]); const [instructions, setInstructions] = useState([]); const [basis, setBasis] = useState(null); const [file, setFile] = useState(null); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => { if (!project) return; try { const [a, b, c] = await Promise.all([cachedGet(`/api/documents?project_id=${project.id}`), cachedGet(`/api/instructions?project_id=${project.id}`), cachedGet(`/api/source-basis?project_id=${project.id}`)]); setDocs(a); setInstructions(b); setBasis(c); } catch (e) { notify(e.message, "error"); } }, [project, sync]);
  useEffect(() => { load(); }, [load]);
  async function submit(e) { e.preventDefault(); if (!file) return; setBusy(true); const fd = new FormData(); fd.append("project_id", project.id); fd.append("file", file); try { await upload("/api/documents", fd); notify("Dokument wgrany i przeanalizowany"); setFile(null); e.target.reset(); load(); } catch (err) { notify(err.message, "error"); } finally { setBusy(false); } }
  if (!project) return <Empty>Wybierz projekt.</Empty>;
  const approved = docs.filter(doc => doc.approved_source); const supplemental = docs.filter(doc => !doc.approved_source); const expected = basis?.expected_sources || 10;
  return <><PageHead eyebrow="TYLKO ZATWIERDZONE DOKUMENTY" title="Baza źródłowa i instrukcje"><span className="badge success">{basis?.registered_sources || 0}/{expected} źródeł</span></PageHead>
    {basis && <section className="source-hero card"><div><p className="eyebrow">JEDYNA BAZA DANYCH TECHNICZNYCH</p><h2>{basis.project.name} · {basis.project.capacity_mw} MWp</h2><p>{basis.policy}</p><small>{basis.project.location}</small></div><div className="source-variants">{basis.templates.map(item => <span key={item.name}>{item.name}</span>)}</div></section>}
    <div className="source-grid"><section className="card"><div className="card-head"><div><p className="eyebrow">{expected} PLIKÓW W PACZCE</p><h2>Zatwierdzone źródła</h2></div></div>{approved.map(doc => <div className="document source-document" key={doc.id}><div className={`file-type ${doc.kind.toLowerCase()}`}>{doc.kind}</div><div><strong>{doc.filename}</strong><small>{doc.role}</small><span className="source-hash">SHA-256 {doc.sha256?.slice(0, 12)}…</span></div><button className="icon-button" title="Pobierz oryginalny plik" onClick={() => download(`/api/documents/${doc.id}/file`, doc.filename)}>↓</button></div>)}</section>
      <section className="card source-summary"><div><p className="eyebrow">ZAKRES MECHANICZNY</p><h2>Co program wykorzystuje</h2></div><div className="scope-columns"><div><strong>Uwzględnione</strong>{basis?.scope.included.map(item => <span key={item}>✓ {item}</span>)}</div><div><strong>Poza zakresem</strong>{basis?.scope.excluded.map(item => <span key={item}>— {item}</span>)}</div></div></section></div>
    <section className="card instruction-panel"><div className="card-head"><div><p className="eyebrow">KROK PO KROKU</p><h2>Instrukcje montażu konstrukcji</h2></div><span className="badge neutral">{instructions.length} etapów</span></div>{instructions.map((item, i) => <details className="instruction source-instruction" key={`${item.document_id}-${i}`} open={i === 0}><summary><span>{item.section || i + 1}</span><strong>{item.title}</strong><small>str. {item.pages}</small></summary><ol>{item.steps?.map((step, index) => <li key={index}>{step}</li>)}</ol>{item.quality && <div className="quality-note"><strong>Kontrola:</strong> {item.quality}</div>}<small>Źródło: {item.source}, strony {item.pages}</small></details>)}</section>
    {basis && <div className="split source-reference"><section className="card"><div className="card-head"><div><p className="eyebrow">TABELA 2</p><h2>Narzędzia</h2></div></div><ul className="tool-list">{basis.tools.items.map(item => <li key={item}>{item}</li>)}</ul><small>{basis.tools.source}</small></section><section className="card"><div className="card-head"><div><p className="eyebrow">MOMENTY Z MANUALA</p><h2>Połączenia kontrolne</h2></div></div><div className="torque-list">{basis.torques.map(item => <div key={item.item}><span>{item.item}<small>{item.source}</small></span><strong>{item.min_nm}–{item.max_nm} N·m</strong></div>)}</div></section></div>}
    <section className="upload-card supplemental-upload"><div className="upload-icon">⇧</div><div><h2>Dodaj plik pomocniczy</h2><p>Plik będzie dostępny w projekcie, lecz nie zmieni instrukcji, wariantów ani bazy BOM, jeśli nie jest jednym z dziesięciu zatwierdzonych źródeł.</p></div><form onSubmit={submit}><label className="file-drop"><input type="file" accept=".pdf,.dwg,.dxf,.xlsx,.xlsm" onChange={e => setFile(e.target.files[0])} /><span>{file?.name || "Wybierz plik"}</span></label><button className="primary" disabled={busy}>{busy ? "Zapisywanie…" : "Dodaj"}</button></form></section>
    {!!supplemental.length && <section className="card"><h2>Pliki pomocnicze</h2>{supplemental.map(doc => <div className="document" key={doc.id}><div className={`file-type ${doc.kind.toLowerCase()}`}>{doc.kind}</div><div><strong>{doc.filename}</strong><small>{fmt(doc.uploaded_at)}</small><span className="badge neutral">{doc.status}</span></div><button className="icon-button" onClick={() => download(`/api/documents/${doc.id}/file`, doc.filename)}>↓</button></div>)}</section>}
  </>;
}

function RfiPage({ project, sync, notify, user, preselectedRow, clearPreselected }) {
  const [items, setItems] = useState([]); const [tree, setTree] = useState(null); const [form, setForm] = useState({ row_id: preselectedRow || "", title: "", description: "", priority: "normalny" }); const [photo, setPhoto] = useState(null);
  const load = useCallback(async () => { if (!project) return; try { const [a, b] = await Promise.all([cachedGet(`/api/rfis?project_id=${project.id}`), cachedGet(`/api/projects/${project.id}/tree`)]); setItems(a); setTree(b); } catch (e) { notify(e.message, "error"); } }, [project, sync]); useEffect(() => { load(); }, [load]); useEffect(() => { if (preselectedRow) { setForm(x => ({ ...x, row_id: preselectedRow })); clearPreselected(); } }, [preselectedRow]);
  const rows = tree?.zones.flatMap(z => z.sections.flatMap(s => s.rows.map(r => ({ ...r, label: `${z.name} / ${s.name} / ${r.code}` })))) || [];
  async function submit(e) { e.preventDefault(); try { const result = await mutate("/api/rfis", "POST", { project_id: project.id, row_id: Number(form.row_id) || null, title: form.title, description: form.description, priority: form.priority, client_id: uid() }); if (!result.queued && photo) { const fd = new FormData(); fd.append("file", photo); await upload(`/api/rfi/${result.id}/photos`, fd); } notify(result.queued ? "RFI zapisane offline" : "RFI wysłane"); setForm({ row_id: "", title: "", description: "", priority: "normalny" }); setPhoto(null); if (!result.queued) load(); } catch (err) { notify(err.message, "error"); } }
  async function status(id, value) { try { await mutate(`/api/rfis/${id}`, "PATCH", { status: value }); notify("Status zmieniony"); load(); } catch (e) { notify(e.message, "error"); } }
  return <><PageHead eyebrow="PROBLEMY I KOLIZJE" title="RFI"><span className="badge danger">{items.filter(x => x.status !== "zamknięty").length} otwartych</span></PageHead><div className="split rfi-layout"><form className="card sticky-form" onSubmit={submit}><h2>Nowe zgłoszenie</h2><label>Rząd<select value={form.row_id} onChange={e => setForm({ ...form, row_id: e.target.value })}><option value="">Problem ogólny</option>{rows.map(row => <option key={row.id} value={row.id}>{row.label}</option>)}</select></label><label>Tytuł<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><label>Opis<textarea required rows="5" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></label><label>Priorytet<select value={form.priority} onChange={e => setForm({ ...form, priority: e.target.value })}><option value="niski">Niski</option><option value="normalny">Normalny</option><option value="wysoki">Wysoki</option><option value="krytyczny">Krytyczny</option></select></label><label className="camera-button"><input type="file" accept="image/*" capture="environment" onChange={e => setPhoto(e.target.files[0])} /><span>▧</span>{photo?.name || "Dodaj zdjęcie"}</label><button className="primary wide">Wyślij RFI</button></form><section className="rfi-list">{items.map(item => <article className="card rfi-card" key={item.id}><div className="rfi-top"><span className={`badge ${["wysoki", "krytyczny"].includes(item.priority) ? "danger" : "warning"}`}>{item.priority}</span><span className={`status-pill ${item.status}`}>{item.status}</span></div><h2>#{item.id} {item.title}</h2><p>{item.description}</p><small>{fmt(item.created_at)} · {item.photos} zdjęć</small>{user.role === "kierownik" && <div className="rfi-controls"><button onClick={() => status(item.id, "w analizie")}>W analizie</button><button onClick={() => status(item.id, "zamknięty")}>Zamknij</button></div>}</article>)}</section></div></>;
}

function Users({ notify, user }) {
  const [items, setItems] = useState([]); const [form, setForm] = useState({ username: "", full_name: "", role: "brygadzista", password: "" }); const load = useCallback(() => { if (user.role === "kierownik") cachedGet("/api/users").then(setItems).catch(e => notify(e.message, "error")); }, [user]); useEffect(() => { load(); }, [load]);
  async function submit(e) { e.preventDefault(); try { await api("/api/users", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) }); notify("Konto utworzone"); setForm({ username: "", full_name: "", role: "brygadzista", password: "" }); load(); } catch (err) { notify(err.message, "error"); } }
  if (user.role !== "kierownik") return <Empty>Tylko kierownik zarządza użytkownikami.</Empty>;
  return <><PageHead eyebrow="TRZY ROLE" title="Użytkownicy" /><div className="split"><section className="card">{items.map(item => <div className="user-row" key={item.id}><div className="avatar">{item.full_name.split(" ").map(x => x[0]).slice(0, 2).join("")}</div><div><strong>{item.full_name}</strong><small>@{item.username}</small></div><span className="badge neutral">{roleName(item.role)}</span></div>)}</section><form className="card" onSubmit={submit}><h2>Nowe konto</h2><label>Imię i nazwisko<input required value={form.full_name} onChange={e => setForm({ ...form, full_name: e.target.value })} /></label><label>Login<input required value={form.username} onChange={e => setForm({ ...form, username: e.target.value })} /></label><label>Rola<select value={form.role} onChange={e => setForm({ ...form, role: e.target.value })}><option value="kierownik">Kierownik Budowy</option><option value="brygadzista">Brygadzista</option><option value="magazynier">Magazynier</option></select></label><label>Hasło<input type="password" minLength="8" required value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /></label><button className="primary wide">Utwórz konto</button></form></div></>;
}

export default function App() {
  const [user, setUser] = useState(null); const [loading, setLoading] = useState(!!getToken()); const [projects, setProjects] = useState([]); const [projectId, setProjectIdState] = useState(Number(localStorage.getItem("asolar_project")) || null); const [page, setPage] = useState("dashboard"); const [sync, setSync] = useState(0); const [online, setOnline] = useState(navigator.onLine); const [queue, setQueue] = useState(queuedCount()); const [toast, setToast] = useState(null); const [preselectedRow, setPreselectedRow] = useState(null);
  const notify = useCallback((message, type = "success") => { setToast({ message, type }); setTimeout(() => setToast(null), 4200); }, []);
  function setProjectId(id) { setProjectIdState(id); if (id) localStorage.setItem("asolar_project", id); else localStorage.removeItem("asolar_project"); setSync(x => x + 1); }
  const loadProjects = useCallback(async () => { try { const result = await api("/api/projects?include_archived=true"); setProjects(result); const active = result.filter(x => !x.archived); const selected = active.find(x => x.id === projectId) || active[0]; if (selected && selected.id !== projectId) setProjectId(selected.id); } catch (e) { notify(e.message, "error"); } }, [projectId]);
  useEffect(() => { if (!getToken()) { setLoading(false); return; } api("/api/auth/me").then(setUser).catch(() => setUser(null)).finally(() => setLoading(false)); }, []);
  useEffect(() => { if (user) loadProjects(); }, [user]);
  useEffect(() => { const update = async () => { setOnline(navigator.onLine); if (navigator.onLine && user) { const sent = await flushQueue(); if (sent) { notify(`Zsynchronizowano ${sent} zapisów`); setSync(x => x + 1); } } setQueue(queuedCount()); }; const unauthorized = () => setUser(null); window.addEventListener("online", update); window.addEventListener("offline", update); window.addEventListener("asolar:queue", update); window.addEventListener("asolar:unauthorized", unauthorized); update(); return () => { window.removeEventListener("online", update); window.removeEventListener("offline", update); window.removeEventListener("asolar:queue", update); window.removeEventListener("asolar:unauthorized", unauthorized); }; }, [user]);
  useEffect(() => { if (!user || !getToken()) return; const protocol = location.protocol === "https:" ? "wss" : "ws"; const ws = new WebSocket(`${protocol}://${location.host}/ws?token=${encodeURIComponent(getToken())}`); ws.onmessage = () => setSync(x => x + 1); const keepalive = setInterval(() => { if (ws.readyState === 1) ws.send("ping"); }, 30000); return () => { clearInterval(keepalive); ws.close(); }; }, [user]);
  const activeProjects = projects.filter(x => !x.archived); const project = activeProjects.find(x => x.id === projectId) || activeProjects[0];
  function navigate(target, rowId = null) { setPage(target); if (rowId) setPreselectedRow(rowId); window.scrollTo({ top: 0, behavior: "smooth" }); }
  if (loading) return <Loader />; if (!user) return <Login onLogin={setUser} />;
  const visible = NAV.filter(([id]) => id !== "users" || user.role === "kierownik"); const common = { project, sync, notify, user };
  return <div className="app-shell"><aside className="sidebar"><div className="logo"><div className="brand-mark">A</div><div><strong>ASOLAR</strong><small>ESET Tracker</small></div></div><nav>{visible.map(([id, label, icon]) => <button key={id} className={page === id ? "active" : ""} onClick={() => navigate(id)}><span>{icon}</span>{label}</button>)}</nav><div className="sidebar-foot"><div className="user-mini"><div className="avatar">{user.full_name.split(" ").map(x => x[0]).slice(0, 2).join("")}</div><div><strong>{user.full_name}</strong><small>{roleName(user.role)}</small></div></div><button className="logout" onClick={() => { setToken(null); setUser(null); }}>Wyloguj</button></div></aside><header className="topbar"><div className="mobile-logo"><div className="brand-mark">A</div><strong>ASOLAR</strong></div><label className="project-select"><span>Aktywny projekt</span><select value={project?.id || ""} onChange={e => setProjectId(Number(e.target.value))}>{activeProjects.map(item => <option key={item.id} value={item.id}>{item.name} · {item.capacity_mw} MW</option>)}</select></label><div className={`connection ${online ? "online" : "offline"}`}><i />{online ? "Online" : "Offline"}{queue > 0 && <b>{queue}</b>}</div><button className="avatar top-avatar" onClick={() => { setToken(null); setUser(null); }}>{user.full_name.split(" ").map(x => x[0]).slice(0, 2).join("")}</button></header><main className="content">{page === "dashboard" && <Dashboard {...common} />}{page === "projects" && <Projects projects={projects} reloadProjects={loadProjects} notify={notify} user={user} setProjectId={setProjectId} projectId={projectId} />}{page === "structure" && <TrackerConfiguration {...common} />}{page === "reports" && <Reports {...common} />}{page === "logistics" && <ProjectDemand {...common} />}{page === "documents" && <Documents {...common} />}{page === "rfi" && <RfiPage {...common} preselectedRow={preselectedRow} clearPreselected={() => setPreselectedRow(null)} />}{page === "users" && <Users {...common} />}</main><nav className="bottom-nav">{visible.map(([id, label, icon]) => <button key={id} className={page === id ? "active" : ""} onClick={() => navigate(id)}><span>{icon}</span><small>{label.split(" ")[0]}</small></button>)}</nav>{toast && <div className={`toast ${toast.type}`}>{toast.type === "error" ? "!" : "✓"}<span>{toast.message}</span></div>}</div>;
}
